import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { LocalStorageService } from '../../services/localStorage/local-storage.service';
import { RouterLink } from '@angular/router';
import { menuUsuarioInterno } from '../../core/menus/ui-menu';
import { menuUsuarioExterno } from '../../core/menus/ue-menu';
import { MenuOption } from '../../shared/sidebar-offcanvas/menu-option/menu-option.component';

@Component({
  selector: 'app-welcome',
  imports: [CommonModule, RouterLink],
  templateUrl: './welcome.component.html',
  styleUrl: './welcome.component.css'
})
export class WelcomeComponent implements OnInit {
  userName = '';
  userType = '';
  welcomeMessage = '';
  menuOptions: MenuOption[] = [];
  private localStorageService = inject(LocalStorageService);

  ngOnInit() {
    this.loadUserData();
  }

  private loadUserData() {
    const userData = this.localStorageService.getUser();

    if (userData && userData.user) {
      this.userName = userData.user.name || 'Usuario';
      this.userType = userData.user.user_type;
      this.setWelcomeMessage();
      this.loadMenuOptions(userData.roles);
    } else {
      this.userName = 'Invitado';
      this.userType = 'EXTERNO';
      this.welcomeMessage = 'Bienvenido al Sistema';
      this.menuOptions = menuUsuarioExterno;
    }
  }

  private setWelcomeMessage() {
    const greetings = [
      '¡Hola', '¡Bienvenido/a', '¡Qué bueno verte', '¡Saludos'
    ];
    const randomGreeting = greetings[Math.floor(Math.random() * greetings.length)];

    this.welcomeMessage = `${randomGreeting}, ${this.userName}!`;
  }

  private loadMenuOptions(roles: string[]) {
    const fullMenu = this.userType === 'INTERNO' ? menuUsuarioInterno : menuUsuarioExterno;
    this.menuOptions = fullMenu
      .filter(option => this.hasPermiso(option.permiso, roles))
      .filter(option => option.label !== 'Inicio');
  }

  hasPermiso(key: string | undefined, roles: string[]): boolean {
    if (!key) {
      return true;
    }
    return roles.some(r => r.toLowerCase().includes(key.toLowerCase()));
  }

  isInternalUser(): boolean {
    return this.userType === 'INTERNO';
  }

  isExternalUser(): boolean {
    return this.userType === 'EXTERNO';
  }

  getIconForOption(option: MenuOption): string {
    return option.icon_fill || option.icon || 'bi-circle';
  }
}